public class UrlPartsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.concurrent.Callable<Object> call) {
        try {
            return call.call();
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("hostOf(http://example.com/docs/index.html)", "example.com",
                safe(() -> UrlParts.hostOf("http://example.com/docs/index.html")));
        check("hostOf(https://api.example.org:8443/v1/users)", "api.example.org",
                safe(() -> UrlParts.hostOf("https://api.example.org:8443/v1/users")));
        check("portOf(http://example.com/docs/index.html)", 80,
                safe(() -> UrlParts.portOf("http://example.com/docs/index.html")));
        check("portOf(https://example.com/)", 443,
                safe(() -> UrlParts.portOf("https://example.com/")));
        check("portOf(https://api.example.org:8443/v1/users)", 8443,
                safe(() -> UrlParts.portOf("https://api.example.org:8443/v1/users")));
        check("pathOf(http://example.com/docs/index.html)", "/docs/index.html",
                safe(() -> UrlParts.pathOf("http://example.com/docs/index.html")));
        check("pathOf(http://example.com) has no path", "/",
                safe(() -> UrlParts.pathOf("http://example.com")));
        check("pathOf drops the query string", "/search",
                safe(() -> UrlParts.pathOf("http://example.com/search?q=java")));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

